import type { Aussehen, Grundriss3dPlan, Raum, RaumTyp, XY } from "./plan";

/*
 * Studentenwohnheim Jamlitzer Straße 9 und 10, 03046 Cottbus (17.10.2026).
 * Zwei gleiche Plattenbauriegel, Haus 1 = Nr. 9, Haus 2 = Nr. 10.
 *
 * Quelle: „Studentenwohnheim Cottbus (Komprimiert).pdf“ (Jadzinski
 * Generalübernehmer, 13.07.2026, Drive-Ordner „Grundrisse aller Einheiten“):
 * je Wohnung eine Seite mit farbigem Flächenplan (Rasterbild) und Raumliste,
 * EG bis 3. OG, 242 Wohnungen. Keine Geschossübersicht, keine Türen und
 * Fenster, keine Maßketten. Die Geschosse sind aus den Seiten zusammengesetzt:
 * - Maßstab 94,77 px/m aus Pixel- gegen Raumflächen aller Seiten. Jede Seite
 *   ist auf ihre Wohnung zentriert; Nachbarseiten wurden pixelgenau
 *   überlagert, daraus die Lage entlang der Zeile (Streuung über die
 *   Geschosse höchstens 0,35 m). Wohnungstrennwand gemessen 0,17 m.
 * - Flur und Abstand der Zeilen von der Hausmeisterseite (halber Zoom, zeigt
 *   beide Zeilen): Raumkante zu Raumkante 2,41 m, lichter Flur 2,10 m.
 * - Gartenzeile WE 05 bis 20 (08 und 16 mit zwei Zimmern), Hofzeile 01 bis 04
 *   und 21 bis 32 mit den Treppenhäusern TH1 (neben 01) und TH2 (zwischen 24
 *   und 25), wie in der Wohnflächenliste vom 22.02.2022. Beide Zeilen enden an
 *   denselben Giebeln (Endwohnungen ohne Nachbarn auf den Seiten).
 * Flächenabgleich: Raumumrisse = die farbigen Flächen der Pläne. Je Wohnung
 * weicht die Summe im Mittel 0,8 % und höchstens 3,7 % von der Raumliste ab
 * (z. B. WE 1.01.07: 20,61 m² laut Liste, 20,67 m² im Modell). Bei 1.01.07,
 * 1.02.07 und 1.03.07 führt die Liste das Bad (4,22 m²) als „Zimmer“; hier Bad.
 *
 * Namen: Räume tragen „(WE hggnn)“ = Haus, Geschoss, Nummer der Bauträger-
 * liste ohne Punkte, also WE 10107 = 1.01.07. Welche davon die Investagon-
 * „Wohnung 1“ (22,00 m²) ist, steht in keiner Unterlage.
 *
 * Annahmen (nicht aus den Plänen):
 * - Außenwände 0,30 m; Innenwände füllen die gezeichneten Fugen.
 * - Treppenhäuser als Rechteck über die Zeilentiefe, beide gleich breit
 *   (3,8 m Lücke). Laut Liste 24,91 und 27,40 m², sie reichen also
 *   wohl in den Flur. Im EG von Haus 2 fehlt der Plan für den Bereich
 *   von 01 bis 04 und TH1 (Eingang, WC). In Haus 1 gibt es 01 und 02 in
 *   keinem Geschoss der PDF, dort bleibt eine Lücke.
 * - Nischen am Flur („Flur NUF 7“, 1,55 m²) und Elektroräume sind die
 *   Weißflächen in der Wohnungszelle.
 * - Türen: Wohnungstür am Flur (0,90 m), Badtür auf der längsten gemeinsamen
 *   Kante (0,75 m). Fenster: je Zimmer und Treppenhaus ein Fenster 1,20 m
 *   mittig in der Fassade (Fotos: ein Fenster je Achse).
 * - 4. OG: in der PDF nicht enthalten; die Fotos zeigen fünf Geschosse, und
 *   die Wohnflächenliste 2022 führt im 4. OG dieselben Nummern und Typen.
 *   Es ist hier eine Kopie des 3. OG.
 * - Lage der Häuser zueinander nach OpenStreetMap (Wege 179989848 und
 *   179989851): parallel, Mitten 34,6 m längs und 53,7 m quer versetzt,
 *   Hofseiten einander zugewandt (Haus 1 ist in der PDF gedreht gezeichnet,
 *   die Nummern laufen gegenläufig). OSM gibt 55 × 18 m an; aus den Plänen
 *   ergeben sich 61 × 17,5 m. Die Breite stimmt, die Länge weicht 10 % ab.
 *   Maßgeblich sind hier die Pläne.
 *
 * Außen nach den Investagon-Fotos (foto_5, Luftbild): Flachdach, Putz hell
 * graublau (Median heller, ungesättigter Pixel auf zwei sonnigen
 * Fassadenfeldern: #d4dbdf, #d0dae0), Dachbahn grau (#7e8483, Median der
 * Dachfläche). Das graue Sockelband (#7b8487) ist nur etwa 0,8 m hoch und
 * nicht eingetragen, weil `sockel` das ganze EG färben würde. Die orangen
 * Lochblechfelder vor den Treppenhäusern und die blau gestrichenen Giebel
 * fehlen. Keine Balkone, keine Gauben.
 */

type Daten = {
  g: number;
  /** Name, Typ, Umriss als x1,y1,x2,y2,… in Metern. */
  raeume: Array<[string, RaumTyp, number[]]>;
  /** Je Wandfläche: äußerer Ring, danach Löcher, je als x1,y1,… */
  waende: number[][][];
  fenster: number[][];
  tueren: number[][];
  decke: number[][];
};

const paare = (z: number[]): XY[] => {
  const p: XY[] = [];
  for (let i = 0; i < z.length; i += 2) p.push([z[i], z[i + 1]]);
  return p;
};

function plan(d: Daten, umbenennen: (name: string) => string = (n) => n): Grundriss3dPlan {
  const raeume: Raum[] = d.raeume.map(([name, typ, z], i) => ({ id: `r${i + 1}`, name: umbenennen(name), typ, punkte: paare(z).map(([x, y]) => ({ x, y })) }));
  return {
    version: 1,
    // Norden zeigt im Plan nach rechts und etwas nach oben (Längsachse 100,7° laut OSM).
    nordWinkel: 79,
    geschoss: d.g,
    waende: [],
    oeffnungen: [],
    raeume,
    flaechen: { waende: d.waende.map((w) => w.map(paare)), fenster: d.fenster.map(paare), tueren: d.tueren.map(paare), decke: d.decke.map(paare) },
  };
}

